import React from 'react';
import { BarChartProps } from './types';
/**

  A bar chart or bar graph is a chart or graph that presents categorical data with rectangular
  bars with heights or lengths using the [AMCharts 5 library](https://www.amcharts.com/docs/v5/)
  
  ### Example Usage:
 
  ```tsx
  import * as React from "react";
  import BarChart from '@walmartluminate/chart-components';
 
  export default () => {
    const data = [{ name: 'John', value: 35654 }, { name: 'Damon', value: 65456 }];

    const xAxisSettings = {
      rendererSettings: {
        minGridDistance: 30,
        minorGridEnabled: true,
      },
      categoryAxisSettings: {
        categoryField: 'name',
      },
    };

    const yAxisSettings = {
      categoryAxisSettings: {
        maxDeviation: 0,
        min: 0,
        extraMax: 0.1,
      }
    };

    const seriesSettings = {
      columnSettings: {
        name: 'Series 1',
        valueYField: 'value',
        sequencedInterpolation: true,
        categoryXField: 'name',
      }
      tooltipSettings: { dy: -25, labelText: '{valueY}' },
    };

    return <BarChart data={data} xAxisSettings={xAxisSettings} yAxisSettings={yAxisSettings} seriesSettings={seriesSettings}/>;
  };
  ```
  
  ### References

  https://www.amcharts.com/docs/v5/charts/xy-chart/
  
  https://www.amcharts.com/docs/v4/concepts/axes/axis-ranges/#Range_labels

 */
export declare const BarChart: React.FC<BarChartProps>;
